Here's a simple Discord bot using **Discord.js v14** that supports **slash commands**. The bot has a single command: `ban`, which allows a user with the appropriate permissions to ban a member.

---

### ✅ Prerequisites:
Make sure you have:
- Node.js (v16 or higher)
- `discord.js` installed (`npm install discord.js`)
- A Discord bot token (create one on [Discord Developer Portal](https://discord.com/developers/applications))
- A bot application with the correct permissions (e.g., `Ban Members`)

---

### 📁 File Structure:
```
/bot
  ├── index.js
  └── commands
      └── ban.js
```

---

### 📜 `index.js`
```js
const { Client, GatewayIntentBits, PermissionsBitField } = require('discord.js');
const { REST } = require('@discordjs/rest');
const { Routes } = require('discord-api-types/v10');

// Replace with your bot token
const token = 'YOUR_BOT_TOKEN';

// Replace with your client ID and application ID
const clientId = 'YOUR_CLIENT_ID';
const applicationId = 'YOUR_APPLICATION_ID';

// Create a new client
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMembers,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent
  ]
});

// Load commands
const commands = [];
const commandFiles = fs.readdirSync('./commands').filter(file => file.endsWith('.js'));

for (const file of commandFiles) {
  const command = require(`./commands/${file}`);
  commands.push(command.data.toJSON());
}

// Register commands
const rest = new REST({ version: '10' }).setToken(token);

(async () => {
  try {
    console.log('Registering commands...');
    await rest.put(Routes.applicationCommands(applicationId), { body: commands });
    console.log('Commands registered successfully.');
  } catch (error) {
    console.error('Error registering commands:', error);
  }
})();

// Event: When the bot is ready
client.once('ready', () => {
  console.log(`Logged in as ${client.user.tag}!`);
});

// Event: Handle interactions
client.on('interactionCreate', async interaction => {
  if (!interaction.isCommand()) return;

  const command = interaction.client.commands.get(interaction.commandName);

  if (!command) {
    console.error(`No command matching ${interaction.commandName}`);
    return;
  }

  try {
    await command.execute(interaction);
  } catch (error) {
    console.error(error);
    await interaction.reply({ content: 'There was an error executing the command.', ephemeral: true });
  }
});

// Login to Discord with your bot's token
client.login(token);
```

---

### 📜 `commands/ban.js`
```js
const { SlashCommandBuilder } = require('@discordjs/builders');

module.exports = {
  data: new SlashCommandBuilder()
    .setName('ban')
    .setDescription('Ban a member from the server.')
    .addUserOption(option => 
      option.setName('user').setDescription('the user to ban')
      .setRequired(true))
    .setDefaultPermission(false),

  async execute(interaction) {
    const user = interaction.options.getUser('user');
    const member = await interaction.guild.members.fetch(user.id);

    // Check if the user is the same as the bot or the user is the owner
    if (user.id === interaction.client.user.id || user.id === interaction.guild.ownerId) {
      return interaction.reply({ content: 'I can\'t ban myself or the server owner.', ephemeral: true });
    }

    // Check if the user is a bot
    if (user.bot) {
      return interaction.reply({ content: 'I can\'t ban a bot.', ephemeral: true });
    }

    // Check if the user is in the server
    if (!member) {
      return interaction.reply({ content: 'That user is not in this server.', ephemeral: true });
    }

    // Check if the user has the required permission
    if (!interaction.member.permissions.has(PermissionsBitField.Flags.BanMembers)) {
      return interaction.reply({ content: 'You don\'t have permission to ban members.', ephemeral: true });
    }

    // Ban the user
    try {
      await member.ban({ reason: 'Banned by: ' + interaction.user.tag });
      interaction.reply({ content: `${user.tag} has been banned.`, ephemeral: true });
    } catch (error) {
      console.error('Error banning user:', error);
      interaction.reply({ content: 'I couldn\'t ban that user.', ephemeral: true });
    }
  }
};
```

---

### 🔧 Setup Instructions:
1. **Create a new bot application** on [Discord Developer Portal](https://discord.com/developers/applications).
2. **Copy the bot token** and replace `YOUR_BOT_TOKEN` in `index.js`.
3. **Set the client ID and application ID** in `index.js`.
4. **Enable the `Ban Members` permission** for your bot in the server settings.
5. **Run the bot** with `node index.js`.

---

### 📌 Notes:
- This bot uses **Discord.js v14** and **slash commands**.
- The `ban` command is only available to users with the `Ban Members` permission.
- The bot will only ban users who are in the server.

Let me know if you want to add more features like a reason, timeout, or unban command!

