``

---

## 💛 3. Load Images

We need to load images for the snake, food, and background. We'll use a `SDL_Texture` for each.

```c
SDL_Texture* loadTexture(SDL_Renderer* renderer, const char* path) {
    SDL_Surface* surface = IMG_Load(path);
    if (!surface) {
        fprintf(stderr, "Failed to load image: %s\n", IMG_GetError());
        exit(1);
    }
    SDL_Texture* texture = SDL_CreateTextureFromSurface(renderer, surface);
    SDL_FreeSurface(surface);
    return texture;
}
```

---

## 🎮 3. Game Loop and Snake Logic

Here's a simplified version of the game loop and snake movement:

```c
typedef struct {
    int x, y;
    int width, height;
    SDL_Texture* texture;
} SnakeSegment;

typedef struct {
    int x, y;
    SDL_Texture* texture;
} Food;

typedef struct {
    int dx, dy; // direction
    int speed;
    int score;
    SnakeSegment* segments;
    int segmentCount;
    int segmentMax;
} Snake;

void initSnake(Snake* snake, int width, int height) {
    snake->dx = 1;
    snake->dy = 0;
    snake->speed = 10;
    snake->score = 0;
    snake->segmentCount = 1;
    snake->segmentMax = 100;
    snake->segments = malloc(snake->segmentMax * sizeof(SnakeSegment));
    for (int i = 0; i < snake->segmentMax; i++) {
        snake->segments[i].x = -i * 20;
        snake->segments[i].y = 0;
        snake->segments[i].width = 20;
        snake->segments[i].height = 20;
        snake->segments[i].texture = loadTexture(renderer, "assets/snake.png");
    }
}

void moveSnake(Snake* snake, Food* food) {
    // Move head
    int headX = snake->segments[0].x + snake->dx * snake->speed;
    int headY = snake->segments[0].y + snake->dy * snake->speed;

    // Check collision
    if (headX < 0 || headX >= SCREEN_WIDTH || headY < 0 || headY >= SCREEN_HEIGHT || 
        (headX == food->x && headY == food->y)) {
        // Game over
        exit(1);
    }

    // Add new head
    SnakeSegment* newSegment = realloc(snake->segments, (snake->segmentCount + 1) * sizeof(SnakeSegment));
    if (!newSegment) exit(1);
    snake->segments = newSegment;
    snake->segments[snake->segmentCount].x = headX;
    snake->segments[snake->segmentCount].y = headY;
    snake->segments[snake->segmentCount].texture = snake->segments[0].texture;
    snake->segmentCount++;

    // Remove tail if not eating
    if (headX != food->x || headY != food->y) {
        for (int i = snake->segmentCount - 1; i > 0; i--) {
            snake->segments[i].x = snake->segments[i - 1].x;
            snake->segments[i].y = snake->segments[i - 1].y;
        }
        snake->segments[0].x = headX;
        snake->segments[0].y = headY;
    } else {
        // Generate new food
        food->x = rand() % (SCREEN_WIDTH / 20) * 20;
        food->y = rand() % (SCREEN_HEIGHT / 20) * 20;
    }
}
```

