### ✅ Features:
- Reads from a text file.
- Counts occurrences of a specified word (case-sensitive).
- Handles line-by-line reading.
- Uses standard C++ libraries.

---

### 📄 C++ Code

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

using namespace std;

int main() {
    // Prompt user for the word to search
    string targetWord;
    cout << "Enter the word to count: ";
    cin >> targetWord;

    // Prompt user for the file name
    string fileName;
    cout << "Enter the file name: ";
    cin >> fileName;

    // Open the file
    ifstream file(fileName);
    if (!file.is_open()) {
        cerr << "Error: Could not open file " << fileName << endl;
        return 1;
    }

    string line;
    int count = 0;

    // Read each line from the file
    while (getline(file, line)) {
        // Split the line into words
        istringstream iss(line);
        string word;

        // Count occurrences of targetWord in the line
        while (iss >> word) {
            if (word == targetWord) {
                count++;
            }
        }
    }

    // Close the file
    file.close();

    // Output the result
    cout << "The word \"" << targetWord << "\" appears " << count << " time(s) in the file." << endl;

    return 0;
}
