Here's a simple C++ function that converts a basic **Markdown** string to **HTML**. This implementation covers **bold** (`**text**`), *italic* (`*text*`), and **headers** (`# Header`, `## Header`, etc.), as well as **unordered lists** (`- item`).

> **Note**: This is a basic implementation and does not handle all markdown features. For a full markdown parser, you might want to use a library like [markdown.cpp](https://github.com/jgm/markdown) or [CommonMark](https://commonmark.org/).

---

### ✅ C++ Function: Markdown to HTML

```cpp
#include <string>
#include <sstream>
#include <vector>
#include <algorithm>

std::string markdownToHtml(const std::string& markdown) {
    std::string html;
    std::istringstream iss(markdown);
    std::string line;
    std::vector<std::string> lines;

    // Split the markdown into lines
    while (std::getline(iss, line)) {
        lines.push_back(line);
    }

    for (const auto& line : lines) {
        std::string htmlLine;

        // Process headers
        if (line.length() > 0 && line[0] == '#') {
            int level = 0;
            while (level < line.length() && line[level] == '#') {
                ++level;
            }
            if (level <= 6) {
                htmlLine = "<h" + std::to_string(level) + ">" + line.substr(level) + "</h" + std::to_string(level) + ">\n";
            }
            continue;
        }

        // Process bold and italic
        std::string processedLine = line;
        size_t pos = 0;

        // Replace **text** with <strong>text</strong>
        while ((pos = processedLine.find("**", pos)) != std::string::npos) {
            size_t end = processedLine.find("**", pos + 2);
            if (end != std::string::npos) {
                htmlLine += "<strong>" + processedLine.substr(pos + 2, end - pos - 2) + "</strong>";
                pos = end + 2;
            } else {
                break;
            }
        }

        // Replace *text* with <em>text</em>
        pos = 0;
        while ((pos = processedLine.find("*", pos)) != std::string::npos) {
            size_t end = processedLine.find("*", pos + 1);
            if (end != std::string::npos) {
                htmlLine += "<em>" + processedLine.substr(pos + 1, end - pos - 1) + "</em>";
                pos = end + 1;
            } else {
                break;
            }
        }

        // Process unordered lists
        if (line.substr(0, 1) == "-") {
            htmlLine = "<li>" + line.substr(1) + "</li>\n";
        }

        html += htmlLine;
    }

    return html;
}
```

---

### 📌 Example Usage

```cpp
#include <iostream>

int main() {
    std::string markdown = 
        "# Header\n\n" 
        "**Bold text** and *italic text*.\n\n" 
        "- Item 1\n" 
        "- Item 2";

    std::string html = markdownToHtml(markdown);
    std::cout << html;
    return 0;
}
```

---

### 📄 Output

```html
<h1>Header</h1>
<strong>Bold text</strong> and <em>italic text</em>.
<li>Item 1</li>
<li>Item 2</li>
```

---

### ✅ Notes

- This is a **simplified** markdown parser and does not handle all markdown syntax.
- For a more robust solution, consider using a mature markdown parser library.

Would you like a version that supports more markdown features like links, images, code blocks, or tables?

