### ✅ Features:
- Reads a file line by line.
- Counts the number of times a specified word appears.
- Case-sensitive by default, but you can modify it to be case-insensitive if needed.

---

### 📄 `word_count.cpp`

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <sstream>

using namespace std;

int main() {
    string filename, targetWord;
    int count = 0;

    // Get the filename and target word from the user
    cout << "Enter the filename: ";
    cin >> filename;

    cout << "Enter the word to count: ";
    cin >> targetWord;

    // Open the file
    ifstream file(filename);
    if (!file.is_open()) {
        cerr << "Error: Could not open the file." << endl;
        return 1;
    }

    string line;
    while (getline(file, line)) {
        // Split the line into words
        istringstream iss(line);
        string word;
        while (iss >> word) {
            // Compare the word with the target word
            if (word == targetWord) {
                count++;
            }
        }
    }

    // Close the file
    file.close();

    // Output the result
    cout << "The word \"" << targetWord << "\" appears " << count << " times in the file." << endl;

    return 0;
}
```

---

